-- PT107-S1-Q23. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT107-S1-Q23$batch12$ AND q.stimulus=$batch12$Linda says that, as a scientist, she knows that no scientist appreciates poetry. And, since most scientists are logical, at least some of the people who appreciate poetry are illogical.$batch12$ AND q.prompt=$batch12$Which one of the following is most parallel in its reasoning to the flawed reasoning above?$batch12$ AND q.correct_choice=$batch12$B$batch12$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q23'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT107-S1-Q23$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q23'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT107-S1-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Some people who appreciate poetry are illogical.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$No scientist appreciates poetry. Most scientists are logical.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: No A are B. Most A are C. So some B are not C. The facts about scientists say nothing about the people who appreciate poetry, since none of them are scientists. The conclusion jumps to a new group.$batch12$), (3, $batch12$Goal$batch12$, $batch12$No A are B, most A are C, so some B are not C.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT107-S1-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$No marsupials lay eggs, most are Australian, so some Australians don't lay eggs. That's valid: the marsupials themselves are those Australians. The original's conclusion is about the excluded group.$batch12$), ($batch12$B$batch12$, $batch12$No fathers want candy at bedtime. Most fathers are adults. So some candy-wanters are not adults. Same recipe, same flaw.$batch12$), ($batch12$C$batch12$, $batch12$This concludes California wine is inferior. That's a claim about the "most" group, not about the excluded group.$batch12$), ($batch12$D$batch12$, $batch12$Valid: most instant film is color, and no color film is that sharp, so some instant film isn't.$batch12$), ($batch12$E$batch12$, $batch12$This says some tax-likers are honest. The original concludes the excluded group lacks the "most" trait, so a match would say some are dishonest.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT107-S1-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
